TEAM_ROWS = {7: "Team intro paragraph", 9: "SEA OtTeRS – intro paragraph"}

if __name__ == "__main__":
    import json, re, sys
    d = json.load(open("sheet_data.json"))
    for (sheet, ref), new in FIX.items():
        col = re.match(r"[A-Z]+", ref).group(); row = int(ref[len(col):])
        ci = ord(col) - ord("A")
        if sheet == "Team info":
            d["team"][TEAM_ROWS[row]] = new
        else:
            key = "people" if sheet == "People" else "news"
            d[key][row - 3][COLS[sheet][ci]] = new
    json.dump(d, open("sheet_data.json", "w"), ensure_ascii=False, indent=1)
    print("applied", len(FIX))
